  "airtahitinui": {"name":"Air Tahiti Nui | Club Tiare","programName":"Club Tiare","country":"PF","currency":"XPF","unit":"miles","method":"distance","defaultFareType":"y-tln","fareTypes":[{"id":"j-cj","name":"Poerava Business (C, J)","rate":1.5},{"id":"j-dz","name":"Poerava Business (D, Z)","rate":1.25},{"id":"w","name":"Mānava Premium (W)","rate":1.15},{"id":"w-eap","name":"Mānava Premium (E, A, P)","rate":1.05},{"id":"y-ymkh","name":"Moana Economy (Y, M, K, H)","rate":1},{"id":"y-tln","name":"Moana Economy (T, L, N)","rate":0.75},{"id":"y-bqgv","name":"Moana Economy (B, Q, G, V)","rate":0.5},{"id":"y-s-paris","name":"Moana Economy (S), Papeete-Paris","rate":0.5},{"id":"y-s","name":"Moana Economy (S), other routes","rate":0.25}],"statuses":[{"id":"member","name":"Club Tiare Member","multiplier":1},{"id":"silver","name":"Silver","multiplier":1.5},{"id":"gold","name":"Gold","multiplier":1.75}],"note":"Club Tiare earns a share of the distance by booking class on Air Tahiti Nui flights: 25% (S) to 150% (Poerava Business C, J); class S earns 50% between Papeete and Paris. Classes O, X, U, I, F and R and infants under 2 earn nothing. Silver earns 50% and Gold 75% more, per the Club Tiare terms. Codeshare flights with Alaska Airlines do not earn."},
  "alaska": {"name":"Alaska Airlines | Atmos Rewards","unit":"points","method":"distance","earnMethods":[{"id":"distance","name":"Miles flown: 1 point per mile"},{"id":"price","name":"Price paid: 5 points per dollar","rate":5},{"id":"segments","name":"Segments flown: 500 points per segment","perSegment":500}],"centsPerPoint":1.4,"statuses":[{"id":"member","name":"Atmos Member","multiplier":1},{"id":"silver","name":"Atmos Silver","multiplier":1.25,"alliance":"Ruby"},{"id":"gold","name":"Atmos Gold","multiplier":1.5,"alliance":"Sapphire"},{"id":"platinum","name":"Atmos Platinum","multiplier":2,"alliance":"Emerald"},{"id":"titanium","name":"Atmos Titanium","multiplier":2.5,"alliance":"Emerald"}],"cards":[{"id":"ascent","name":"Atmos Rewards Ascent Visa Signature","rate":3,"bank":"Bank of America (US)"},{"id":"summit","name":"Atmos Rewards Summit Visa Infinite","rate":3,"bank":"Bank of America (US)"}],"note":"Atmos Rewards members choose how they earn for flights departing on or after 1 January 2027: 1 point per mile flown, 5 points per dollar of the fare, or 500 points per segment. Silver, Gold, Platinum, and Titanium add 25% to 150%. Members who never chose keep earning by distance; new members default to price paid. Price paid excludes taxes, and Basic Economy fares may not qualify. Flights before 2027 earn by distance.","alliance":"oneworld"},
  "allegiant": {"name":"Allegiant Air | Allways Rewards","addons":true,"baseFareOnly":true,"carrierLabel":"Carrier Usage Charge","carrierHint":"Allegiant's per-segment charge for booking online or by phone. It does not earn points.","unit":"points","method":"tiered","centsPerPoint":1,"tiers":[{"upTo":500,"rate":1},{"upTo":Infinity,"rate":2}],"statuses":[{"id":"member","name":"Allways Rewards Member"}],"cards":[{"id":"allways-visa","name":"Allways Rewards Visa","rate":3,"bank":"Bank of America (US)"}],"note":"Allways Rewards has no elite status tiers. Members earn 1 point per dollar on the first $500 of a booking and 2 points per dollar above $500, on the fare plus seats and bags, excluding taxes and fees."},
  "american": {"name":"American Airlines | AAdvantage","programName":"AAdvantage","unit":"miles","addons":true,"addonsLabel":"Paid Upgrades","addonsHint":"The base price of a cabin upgrade bought from American. It earns miles at your status rate.","airlines":[{"id":"aa","name":"American Airlines","country":"US","alliance":"oneworld"},{"id":"fj","name":"Fiji Airways","country":"FJ","program":{"cap":null,"cards":null,"addons":false,"note":"Fiji Airways uses AAdvantage. Flights sold by Fiji Airways earn like American flights: 5 miles per US dollar of the base fare and carrier-imposed fees, with a 40%, 60%, 80%, or 120% bonus for Gold, Platinum, Platinum Pro, and Executive Platinum. Government taxes do not earn. LITE fares bought on or after 17 December 2025 earn nothing. Fiji fares are often priced in Fiji dollars, so enter the US dollar equivalent."},"alliance":"oneworld"}],"method":"spend","cap":75000,"centsPerPoint":1.4,"statuses":[{"id":"member","name":"AAdvantage Member","rate":5},{"id":"gold","name":"AAdvantage Gold","rate":7,"alliance":"Ruby"},{"id":"platinum","name":"AAdvantage Platinum","rate":8,"alliance":"Sapphire"},{"id":"platpro","name":"AAdvantage Platinum Pro","rate":9,"alliance":"Sapphire"},{"id":"exp","name":"AAdvantage Executive Platinum","rate":11,"alliance":"Emerald"}],"cards":[{"id":"citi-mileup","name":"Citi / AAdvantage MileUp","rate":2,"bank":"Citi (US)"},{"id":"citi-platselect","name":"Citi / AAdvantage Platinum Select","rate":2,"bank":"Citi (US)"},{"id":"citi-globe","name":"Citi / AAdvantage Globe","rate":3,"bank":"Citi (US)"},{"id":"citi-exec","name":"Citi / AAdvantage Executive","rate":4,"bank":"Citi (US)"}],"note":"AAdvantage miles are earned on base fare and carrier-imposed fees, and on paid upgrades at the same rate. Government taxes, bags, and seats do not earn miles. Earning is capped at 75,000 miles per ticket."},
